css:
.loader { position: relative; width: var(--loader-size); height: var(--loader-size); }
.loader span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size) * .15); height: calc(var(--loader-size) * .15); margin: calc(var(--loader-size) * -.075) 0 0 calc(var(--loader-size) * -.075); border-radius: 9999px; background: var(--loader-color); animation: twDotFade calc(var(--loader-speed) * 1.2) linear infinite; }
.loader span:nth-child(1) { transform: rotate(0deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -.15); }
.loader span:nth-child(2) { transform: rotate(45deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -.3); }
.loader span:nth-child(3) { transform: rotate(90deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -.45); }
.loader span:nth-child(4) { transform: rotate(135deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -.6); }
.loader span:nth-child(5) { transform: rotate(180deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -.75); }
.loader span:nth-child(6) { transform: rotate(225deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -.9); }
.loader span:nth-child(7) { transform: rotate(270deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -1.05); }
.loader span:nth-child(8) { transform: rotate(315deg) translateY(calc(var(--loader-size) * -.38)); animation-delay: calc(var(--loader-speed) * -1.2); }
@keyframes twDotFade { 0% { opacity: 1; } 100% { opacity: .12; } }

tailwind:
{/* keyframes twDotFade: opacity 1 -> .12; place each dot with rotate(n*45deg) translateY(-24px) */}
<div className="relative h-16 w-16">
  {[0, 45, 90, 135, 180, 225, 270, 315].map((angle, index) => (
    <span
      key={angle}
      className="absolute left-1/2 top-1/2 h-2.5 w-2.5 animate-[twDotFade_1.2s_linear_infinite] rounded-full bg-amber-500"
      style={{ margin: "-5px 0 0 -5px", transform: "rotate(" + angle + "deg) translateY(-24px)", animationDelay: -150 * (index + 1) + "ms" }}
    />
  ))}
</div>
